import React from 'react';
import './Header.css'; 

const ContactUs = () => {
  return (
    <main className="container" style={{ padding: '3rem 0' }}>
      <h1>Contact Us</h1>
      <p style={{ marginTop: '1rem', lineHeight: 1.6 }}>
        We'd love to hear from you. Reach out with questions, feedback or partnership
        inquiries and we'll get back to you as soon as possible.
      </p>

      <section style={{ marginTop: '2rem' }}>
        <h2>Customer Support</h2>
        <p>Phone: <strong>0762294533</strong></p>
        <p>Email: <strong>contact@ravindrastoreslk@gmail.com</strong></p>
        <p>Address: <strong>SLIIT Malabe</strong></p>
      </section>

      <section style={{ marginTop: '2rem' }}>
        <h2>Business Hours</h2>
        <p>Mon - Fri: 8:00 AM — 8:00 PM</p>
        <p>Sat - Sun: 9:00 AM — 6:00 PM</p>
      </section>
    </main>
  );
};

export default ContactUs;
